    // hashmap to keep track of messages printed in the last three seconds
    Map<String, Integer> tm = new HashMap<>();
    int i = 3;

    // traverse the map to check if the message has been printed in the last three seconds
    for(String s : tm.keySet()) {
        if(timestamp - tm.get(s) >= i) {
            tm.remove(s);
        }
    }

    // if the message has not been printed in the last three seconds, print it and add to the map
