private static java.util.concurrent.Executors cleanupExecutor;
static {
	if (cleanupExecutor == null) {
		cleanupExecutor = java.util.concurrent.Executors.newSingleThreadScheduledExecutor();
	}
}

public static void forceDeleteOnExit(File file) throws IOException {
	if (file == null) {
		throw new NullPointerException("file");
	}

	cleanupExecutor.schedule(() -> doForceDelete(file), 0, java.util.concurrent.TimeUnit.MILLISECONDS);
}

private static void doForceDelete(File file) throws IOException {
	if (file.isDirectory()) {
		forceDeleteAllFiles(file);
	}
	if (file.isFile()) {
		file.delete();
	}
}

private static void forceDeleteAllFiles(File directory) throws IOException {
	File[] files = directory.listFiles();
	if (files != null) {
		for (File file : files) {
			doForceDelete(file);
		}
	}
}

