private void addReverse(final File[] files) {
    if (files == null) {
        throw new IllegalArgumentException("File array cannot be null");
    }

    // Create a temporary array to hold the reversed files
    File[] reversedFiles = new File[files.length];

    // Fill the temporary array with the reversed order of files
    for (int i = 0; i < files.length; i++) {
        reversedFiles[i] = files[files.length - 1 - i];
    }

    // Replace the original array with the reversed array
    System.arraycopy(reversedFiles, 0, files, 0, files.length);
}

